/* 恢复出厂：清空备份域，随后重新配置 RTC */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

BKP_DeInit();   /* 备份寄存器内容与 RTC 配置全部清零 */

/* 之后要重新选 RTC 时钟源并重新走 RTC 初始化流程 */
RCC_LSEConfig(RCC_LSE_ON);
while (RCC_GetFlagStatus(RCC_FLAG_LSERDY) == RESET) {}
RCC_RTCCLKConfig(RCC_RTCCLKSource_LSE);
RCC_RTCCLKCmd(ENABLE);

/* PC13 作为 Tamper 输入：机械开关，平时低电平，被打开时拉高 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOC, ENABLE);
GPIO_InitTypeDef GPIO_InitStructure;
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_13;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IPD;   /* 下拉，空闲为低 */
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
GPIO_Init(GPIOC, &GPIO_InitStructure);

RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

/* 高电平触发为入侵 */
BKP_TamperPinLevelConfig(BKP_TamperPinLevel_High);
BKP_TamperPinCmd(ENABLE);

/* Tamper 检测 + 中断告警 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

BKP_TamperPinLevelConfig(BKP_TamperPinLevel_High);
BKP_ClearFlag();                     /* 先清掉可能残留的旧事件标志 */
BKP_TamperPinCmd(ENABLE);
BKP_ITConfig(ENABLE);

/* NVIC 里使能 TAMPER_IRQn，中断服务函数名 TAMPER_IRQHandler */

/* NVIC 使能 Tamper 中断通道 */
NVIC_InitTypeDef NVIC_InitStructure;
NVIC_InitStructure.NVIC_IRQChannel = TAMPER_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x02;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x00;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

BKP_ClearITPendingBit();
BKP_ITConfig(ENABLE);

/* 中断服务函数名必须与启动文件一致 */
void TAMPER_IRQHandler(void)
{
  if (BKP_GetITStatus() != RESET)
  {
    BKP_ClearITPendingBit();   /* 不清会反复进中断 */
    /* 告警处理：记录、擦密钥、点亮指示灯 */
  }
}

/* 从 PC13 输出 RTC 秒脉冲，用于驱动 LED 秒闪 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOC | RCC_APB2Periph_AFIO, ENABLE);
GPIO_InitTypeDef GPIO_InitStructure;
GPIO_InitStructure.GPIO_Pin = GPIO_Pin_13;
GPIO_InitStructure.GPIO_Mode = GPIO_Mode_AF_PP;   /* 复用推挽 */
GPIO_InitStructure.GPIO_Speed = GPIO_Speed_2MHz;
GPIO_Init(GPIOC, &GPIO_InitStructure);

RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

BKP_RTCOutputConfig(BKP_RTCOutputSource_Second);   /* 1Hz 秒脉冲 */

/* 把 RTC 调慢约 20ppm：每 2^20 个周期减去 21 个周期 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

RTC_WaitForLastTask();
RTC_EnterConfigMode();          /* 必须在配置模式下改校准值 */
BKP_SetRTCCalibrationValue(21); /* 0~0x7F，越大越慢 */
RTC_ExitConfigMode();
RTC_WaitForLastTask();

/* 想精确测量：从 PC13 输出 512Hz 用频率计比对 */
BKP_RTCOutputConfig(BKP_RTCOutputSource_CalibClock);

#define MAGIC_INIT  0xA55Au

/* 上电初始化：判断备份域数据是否有效 */
RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);   /* 关键：不开这个开关写不进去 */
BKP_ClearFlag();               /* 关键：Tamper 标志置位时写操作可能被拒绝 */

if (BKP_ReadBackupRegister(BKP_DR1) != MAGIC_INIT)
{
  /* 首次上电或备份域已丢失：初始化 */
  BKP_WriteBackupRegister(BKP_DR1, MAGIC_INIT);
  BKP_WriteBackupRegister(BKP_DR2, 0x0000);   /* 例如累计运行次数 */
}
else
{
  /* 备份域数据有效，可以取出之前保存的参数 */
  uint16_t counter = BKP_ReadBackupRegister(BKP_DR2);
}

RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

/* 用魔数判断备份域数据是否可信 */
if (BKP_ReadBackupRegister(BKP_DR1) == 0xA55A)
{
  /* 备份域有效：取回上次保存的运行时长 */
  uint32_t seconds = ((uint32_t)BKP_ReadBackupRegister(BKP_DR3) << 16)
                   | BKP_ReadBackupRegister(BKP_DR4);
}
else
{
  /* 首次上电或 VBAT 掉电，重新初始化 */
}

RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

/* 上电自检：是否被拆过机 */
if (BKP_GetFlagStatus() != RESET)
{
  BKP_ClearFlag();          /* 清掉，否则每次上电都会报警 */
  /* 例如：擦除密钥、记录一次入侵、点亮告警灯 */
}

RCC_APB1PeriphClockCmd(RCC_APB1Periph_PWR | RCC_APB1Periph_BKP, ENABLE);
PWR_BackupAccessCmd(ENABLE);

/* 推荐顺序：先清标志，再写备份寄存器 */
BKP_ClearFlag();
BKP_WriteBackupRegister(BKP_DR1, 0xA55A);
BKP_WriteBackupRegister(BKP_DR2, 0x1234);

void TAMPER_IRQHandler(void)
{
  if (BKP_GetITStatus() != RESET)
  {
    BKP_ClearITPendingBit();
    /* 确认是 Tamper 中断后的处理 */
  }
}

void TAMPER_IRQHandler(void)
{
  if (BKP_GetITStatus() != RESET)
  {
    BKP_ClearITPendingBit();   /* 清中断标志 */
    BKP_ClearFlag();           /* 事件标志也清掉，避免下次上电误判 */
    /* 业务处理 */
  }
}
